CREATE TABLE IF NOT EXISTS cms_sites(id INTEGER PRIMARY KEY AUTOINCREMENT,site_key TEXT NOT NULL UNIQUE,name TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active' CHECK(status IN('active','staging','suspended','archived')),owner_user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,agency_key TEXT NOT NULL DEFAULT '',default_locale TEXT NOT NULL DEFAULT 'en',settings_json TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS cms_site_domains(id INTEGER PRIMARY KEY AUTOINCREMENT,site_id INTEGER NOT NULL REFERENCES cms_sites(id) ON DELETE CASCADE,domain TEXT NOT NULL UNIQUE,is_primary INTEGER NOT NULL DEFAULT 0 CHECK(is_primary IN(0,1)),verification_token TEXT NOT NULL DEFAULT '',verified_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_cms_site_domains_site ON cms_site_domains(site_id,is_primary);
CREATE TABLE IF NOT EXISTS cms_site_memberships(site_id INTEGER NOT NULL REFERENCES cms_sites(id) ON DELETE CASCADE,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,site_role TEXT NOT NULL DEFAULT 'editor' CHECK(site_role IN('owner','admin','editor','author','support','viewer')),permissions_json TEXT NOT NULL DEFAULT '[]',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(site_id,user_id));
CREATE TABLE IF NOT EXISTS cms_site_settings(site_id INTEGER NOT NULL REFERENCES cms_sites(id) ON DELETE CASCADE,setting_key TEXT NOT NULL,setting_value TEXT NOT NULL DEFAULT '',updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(site_id,setting_key));
CREATE TABLE IF NOT EXISTS cms_site_extensions(site_id INTEGER NOT NULL REFERENCES cms_sites(id) ON DELETE CASCADE,extension_key TEXT NOT NULL,is_enabled INTEGER NOT NULL DEFAULT 1 CHECK(is_enabled IN(0,1)),config_json TEXT NOT NULL DEFAULT '{}',updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(site_id,extension_key));
CREATE TABLE IF NOT EXISTS cms_site_connectors(site_id INTEGER NOT NULL REFERENCES cms_sites(id) ON DELETE CASCADE,connector_key TEXT NOT NULL,connector_id INTEGER REFERENCES service_connectors(id) ON DELETE SET NULL,policy_json TEXT NOT NULL DEFAULT '{}',updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(site_id,connector_key));
CREATE TABLE IF NOT EXISTS cms_site_clones(id INTEGER PRIMARY KEY AUTOINCREMENT,source_site_id INTEGER NOT NULL REFERENCES cms_sites(id) ON DELETE CASCADE,target_site_id INTEGER NOT NULL REFERENCES cms_sites(id) ON DELETE CASCADE,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN('pending','running','completed','failed')),details_json TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,finished_at TEXT);
INSERT OR IGNORE INTO cms_sites(id,site_key,name,status,default_locale,settings_json) VALUES(1,'default','Default Site','active','en','{}');
